public class Main {
    static class FixedWindowLimiter {
        final long windowMs;
        final int limit;
        long currentWindow = -1;
        int count = 0;
        FixedWindowLimiter(long windowMs, int limit) { this.windowMs = windowMs; this.limit = limit; }
        boolean allow(long now) {
            long window = now / windowMs;
            if (window != currentWindow) count = 0;
            currentWindow = window;
            if (count >= limit) return false;
            count++;
            return true;
        }
    }
    public static void main(String[] args) {
        FixedWindowLimiter rl = new FixedWindowLimiter(1000, 3);
        long[] times = {0, 100, 200, 300, 999, 1000, 1001};
        StringBuilder sb = new StringBuilder();
        for (long t : times) sb.append(t).append(rl.allow(t) ? ":ok " : ":deny ");
        System.out.println(sb.toString().trim());
    }
}

