public class Main {
    static class LeakyBucket {
        final double capacity, leakPerMs;
        double water = 0;
        long last = 0;
        LeakyBucket(double capacity, double leakPerSec) {
            this.capacity = capacity;
            this.leakPerMs = leakPerSec / 1000.0;
        }
        boolean offer(long now) {
            double leaked = (now - last) * leakPerMs;
            water = Math.max(0, water - leaked);
            last = now;
            if (water + 1 > capacity) return false;
            water += 1;
            return true;
        }
    }
    public static void main(String[] args) {
        LeakyBucket b = new LeakyBucket(2, 1);
        long[] times = {0, 0, 0, 500, 1000, 1000, 3000};
        StringBuilder sb = new StringBuilder();
        for (long t : times) sb.append(t).append(b.offer(t) ? ":ok " : ":drop ");
        System.out.println(sb.toString().trim());
    }
}

public class Main {
    static class FakeClock {
        long now = 0;
        void sleep(long ms) { now += ms; }
    }
    interface Op { String call(int attempt) throws Exception; }
    static String retry(Op op, int maxAttempts, long baseMs, long capMs, FakeClock clock) throws Exception {
        for (int attempt = 0; ; attempt++) {
            try {
                return op.call(attempt);
            } catch (Exception e) {
                if (attempt + 1 >= maxAttempts) throw e;
                long delay = Math.min(capMs, baseMs * (1L << attempt));
                System.out.println("attempt " + attempt + " failed, sleeping " + delay + "ms");
                clock.sleep(delay);
            }
        }
    }
    public static void main(String[] args) throws Exception {
        FakeClock clock = new FakeClock();
        String r = retry(a -> {
            if (a < 4) throw new Exception("timeout");
            return "ok";
        }, 6, 100, 500, clock);
        System.out.println(r + " at t=" + clock.now + "ms");
    }
}

