public class Main {
    static class TokenBucket {
        final double capacity, refillPerMs;
        double tokens;
        long last;
        TokenBucket(double capacity, double refillPerSec, long now) {
            this.capacity = capacity;
            this.refillPerMs = refillPerSec / 1000.0;
            this.tokens = capacity;
            this.last = now;
        }
        boolean tryAcquire(long now) {
            long elapsed = now - last;
            tokens = Math.min(capacity, tokens + elapsed * refillPerMs);
            last = now;
            if (tokens < 1.0) return false;
            tokens -= 1.0;
            return true;
        }
    }
    public static void main(String[] args) {
        TokenBucket b = new TokenBucket(3, 2, 0);
        long[] times = {0, 0, 0, 0, 250, 500, 500, 2000, 2000, 2000, 2000};
        StringBuilder sb = new StringBuilder();
        for (long t : times) sb.append(t).append(b.tryAcquire(t) ? ":ok " : ":deny ");
        System.out.println(sb.toString().trim());
    }
