import java.util.Random;

public class Main {
    static final long BASE_MS = 100, CAP_MS = 2000;
    static long fullJitter(int attempt, Random rnd) {
        long ceiling = Math.min(CAP_MS,
            BASE_MS * (1L << attempt));
        return (long) (rnd.nextDouble() * ceiling);
    }

    static long equalJitter(int attempt, Random rnd) {
        long ceiling = Math.min(CAP_MS,
            BASE_MS * (1L << attempt));
        long half = ceiling / 2;
        return half + (long) (rnd.nextDouble() * half);
    }
    public static void main(String[] args) {
        Random r1 = new Random(42), r2 = new Random(42);
        for (int a = 0; a < 6; a++) {
            System.out.println("attempt " + a + ": full=" + fullJitter(a, r1) + " equal=" + equalJitter(a, r2));
        }
    }
}

public class Main {
    enum State { CLOSED, OPEN, HALF_OPEN }
    static class Breaker {
        State state = State.CLOSED;
        int failures = 0;
        long openedAt = 0;
        final int threshold;
        final long coolDownMs;
        Breaker(int threshold, long coolDownMs) { this.threshold = threshold; this.coolDownMs = coolDownMs; }
        boolean allowRequest(long now) {
            if (state == State.OPEN && now - openedAt >= coolDownMs) {
                state = State.HALF_OPEN;
            }
            return state != State.OPEN;
        }
        void onResult(boolean ok, long now) {
            if (ok) {
                state = State.CLOSED; failures = 0;
            } else if (state == State.HALF_OPEN || ++failures >= threshold) {
                state = State.OPEN; openedAt = now; failures = 0;
            }
        }
    }
    public static void main(String[] args) {
        Breaker b = new Breaker(3, 1000);
        long[] ts = {0, 10, 20, 500, 1100, 1500, 2200, 2300};
        boolean[] ok = {false, false, false, true, false, true, true, true};
        for (int i = 0; i < ts.length; i++) {
            if (!b.allowRequest(ts[i])) {
                System.out.println("t=" + ts[i] + " rejected fast (" + b.state + ")");
                continue;
            }
            b.onResult(ok[i], ts[i]);
            System.out.println("t=" + ts[i] + " " + (ok[i] ? "ok" : "fail") + " -> " + b.state);
        }
    }
}

