import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

public class Main {
    static final Semaphore bulkhead =
        new Semaphore(2);

    static String call(String name) throws Exception {
        if (!bulkhead.tryAcquire(10, TimeUnit.MILLISECONDS)) {
            return name + ": rejected, bulkhead full";
        }
        return name + ": admitted";
    }

    static void done() { bulkhead.release(); }
    public static void main(String[] args) throws Exception {
        System.out.println(call("a"));
        System.out.println(call("b"));
        System.out.println(call("c"));
        done();
        System.out.println(call("d"));
        System.out.println("free permits: " + bulkhead.availablePermits());
    }
}

