import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    static class SlidingLog {
        final Deque<Long> log = new ArrayDeque<>();
        final long windowMs;
        final int limit;
        SlidingLog(long windowMs, int limit) { this.windowMs = windowMs; this.limit = limit; }
        boolean allow(long now) {
            while (!log.isEmpty() && log.peekFirst() <= now - windowMs) {
                log.pollFirst();
            }
            if (log.size() >= limit) return false;
            log.addLast(now);
            return true;
        }
    }
    public static void main(String[] args) {
        SlidingLog rl = new SlidingLog(1000, 3);
        long[] times = {0, 300, 600, 900, 1000, 1299, 1300, 1601};
        StringBuilder sb = new StringBuilder();
        for (long t : times) sb.append(t).append(rl.allow(t) ? ":ok " : ":deny ");
        System.out.println(sb.toString().trim());
    }
}

