public class Main {
    static final long windowMs = 1000;
    static final int limit = 4;
    static long curWindow = -1;
    static int prevCount = 0, curCount = 0;

    boolean allow(long now) {
        long window = now / windowMs;
        if (window != curWindow) {
            prevCount =
                (window == curWindow + 1) ? curCount : 0;
            curCount = 0;
            curWindow = window;
        }
        double frac = (now % windowMs) / (double) windowMs;
        double est = prevCount * (1 - frac) + curCount;
        if (est >= limit) return false;
        curCount++;
        return true;
    }
    public static void main(String[] args) {
        Main rl = new Main();
        long[] times = {100, 200, 300, 400, 500, 1250, 1260, 1500, 1800, 2900};
        StringBuilder sb = new StringBuilder();
        for (long t : times) sb.append(t).append(rl.allow(t) ? ":ok " : ":deny ");
        System.out.println(sb.toString().trim());
    }
}

