public class Main {
    static class MongoException extends RuntimeException {
        final Set<String> labels;
        MongoException(String msg, String... labels) { super(msg); this.labels = Set.of(labels); }
        boolean hasErrorLabel(String l) { return labels.contains(l); }
    }
    static final Deque<MongoException> failures = new ArrayDeque<>();
    static int commits = 0;
    static String runTransaction() {
        if (!failures.isEmpty()) throw failures.poll();
        commits++;
        return "committed (commits=" + commits + ")";
    }
    static String runWithRetry(int maxAttempts) {
        for (int attempt = 1; ; attempt++) {
            try {
                return runTransaction();
            } catch (MongoException e) {
                System.out.println("attempt " + attempt + ": " + e.getMessage());
                if (!e.hasErrorLabel("TransientTransactionError") || attempt >= maxAttempts) throw e;
            }
        }
    }
    public static void main(String[] args) {
        failures.add(new MongoException("WriteConflict", "TransientTransactionError"));
        failures.add(new MongoException("NotWritablePrimary during election", "TransientTransactionError"));
        System.out.println(runWithRetry(5));
        failures.add(new MongoException("DuplicateKey"));
        try {
            runWithRetry(5);
        } catch (MongoException e) {
            System.out.println("gave up: " + e.getMessage());
        }
    }
}

