public class Main {
    static class RetryBudget {
        final double ratio;
        int requests = 0, retries = 0;
        RetryBudget(double ratio) { this.ratio = ratio; }
        void onRequest() { requests++; }

        boolean canRetry() {
            if (retries + 1 > ratio * requests) return false;
            retries++;
            return true;
        }
    }
    public static void main(String[] args) {
        RetryBudget budget = new RetryBudget(0.1);
        int allowed = 0, denied = 0;
        for (int i = 0; i < 50; i++) {
            budget.onRequest();
            if (budget.canRetry()) allowed++; else denied++;
        }
        System.out.println("requests=" + budget.requests + " retries=" + allowed + " denied=" + denied);
        System.out.println("naive 3 retries each would add " + (50 * 3) + " extra calls");
    }
}

public class Main {
    static class FakeClock { long now = 0; }
    static final FakeClock clock = new FakeClock();
    static final long perCallCapMs = 200;
    static class DeadlineExceeded extends RuntimeException {
        DeadlineExceeded(String m) { super(m); }
    }
    static String callService(String name, long deadline, long costMs) {
        long remaining = deadline - clock.now;
        if (remaining <= 0) throw new DeadlineExceeded(name + ": no budget left");
        long timeout = Math.min(remaining, perCallCapMs);
        if (costMs > timeout) {
            clock.now += timeout;
            throw new DeadlineExceeded(name + ": timed out after " + timeout + "ms");
        }
        clock.now += costMs;
        return name + " ok, " + (deadline - clock.now) + "ms left";
    }
    static void handle(long budgetMs) {
        long deadline = clock.now + budgetMs;
        System.out.println("request with " + budgetMs + "ms budget");
        try {
            System.out.println("  " + callService("auth", deadline, 40));
            System.out.println("  " + callService("mongo-find", deadline, 180));
            System.out.println("  " + callService("pricing", deadline, 50));
        } catch (DeadlineExceeded e) {
            System.out.println("  504: " + e.getMessage());
        }
    }
    public static void main(String[] args) {
        handle(400);
        handle(200);
    }
}

