public class Main {
    static class MongoException extends RuntimeException {
        final Set<String> labels;
        MongoException(String msg, String... labels) { super(msg); this.labels = Set.of(labels); }
        boolean hasErrorLabel(String l) { return labels.contains(l); }
    }
    static class Session {
        int commitCalls = 0, applied = 0;
        void commitTransaction() {
            commitCalls++;
            if (applied == 0) applied++;
            if (commitCalls == 1) throw new MongoException("network error", "UnknownTransactionCommitResult");
            if (commitCalls == 2) throw new MongoException("writeConcern wtimeout", "UnknownTransactionCommitResult");
        }
    }
    static void commitWithRetry(Session s) {
        while (true) {
            try {
                s.commitTransaction();
                System.out.println("commit acknowledged");
                return;
            } catch (MongoException e) {
                if (e.hasErrorLabel("UnknownTransactionCommitResult")) {
                    System.out.println("retry commit");
                    continue;
                }
                throw e;
            }
        }
    }
    public static void main(String[] args) {
        Session s = new Session();
        commitWithRetry(s);
        System.out.println("commit calls=" + s.commitCalls + " applied=" + s.applied);
    }
}

import java.util.HashMap;
import java.util.Map;

public class Main {
    record Doc(long window, int count, long version) {}
    static class SharedStore {
        final Map<String, Doc> docs = new HashMap<>();
        Runnable hook = null;
        int casFailures = 0;
        Doc read(String k) { return docs.getOrDefault(k, new Doc(-1, 0, 0)); }
        Doc readForUpdate(String k) {
            Doc d = read(k);
            if (hook != null) { Runnable h = hook; hook = null; h.run(); }
            return d;
        }
        boolean compareAndSet(String k, long expectedVersion, Doc next) {
            if (read(k).version() != expectedVersion) { casFailures++; return false; }
            docs.put(k, next);
            return true;
        }
    }
    static final SharedStore store = new SharedStore();
    static boolean allow(String key, long now, long windowMs, int limit) {
        long window = now / windowMs;
        while (true) {
            Doc cur = store.readForUpdate(key);
            int count = cur.window() == window ? cur.count() : 0;
            if (count >= limit) return false;
            Doc next = new Doc(window, count + 1, cur.version() + 1);
            if (store.compareAndSet(key, cur.version(), next)) return true;
        }
    }
    public static void main(String[] args) {
        System.out.println("A1: " + allow("user:42", 0, 1000, 2));
        store.hook = () -> System.out.println("B1 sneaks in: " + allow("user:42", 5, 1000, 2));
        System.out.println("A2: " + allow("user:42", 5, 1000, 2));
        System.out.println("casFailures=" + store.casFailures + " count=" + store.read("user:42").count());
        System.out.println("A3 next window: " + allow("user:42", 1000, 1000, 2));
    }
}
